        inline_exchange_re = re.compile(
            r"name of (?:each )?exchange on which registered\s+(?:the )?(?:new york stock exchange|nasdaq(?: global select market| global market| capital market)?|chicago stock exchange,? inc\.?)",
            re.IGNORECASE,
